    code: ['// 配置寻址：namespace（环境隔离）· group（租户/业务线）· dataId（常带文件名后缀）', 'Config config = nacos.getConfig("order-service.yaml", "DEFAULT_GROUP", "dev");', '// 启动全量拉取打底，内容与 MD5 指纹一起落本地缓存；运行期靠指纹识别变更', 'String md5 = digest(remote);  // 与本地指纹一致 → 配置没变，不触发刷新', '// 动态监听：30s 长轮询请求挂服务端，无变更超时返回并自动重挂', 'config.addListener(dataId, listener);  // 服务端发布即推送，秒级生效', '// 发布即版本 +1，历史全保留；灰度先发小流量实例验证', 'nacos.publishConfig(dataId, group, content);  // 出问题随时回滚', '// 回滚 = 把上一版本再发布一次：走同样的推送通道，客户端自动恢复'],
