    metrics: [['acquires', '获取锁', '次'], ['releases', '释放锁', '次'], ['queued', '排队入列', '次'], ['woken', 'Watch 唤醒', '次']],
    nodes: [['clients', '竞争客户端', '抢同一把分布式锁', 'Users', 'blue'], ['lock', '锁节点', '/lock · EPHEMERAL', 'Lock', 'yellow'], ['ephemeral', '临时节点语义', '与会话绑定 · 自动清理', 'Clock', 'pink'], ['watch', 'Watch 机制', '一次性 · NodeDeleted', 'LocateFixed', 'green'], ['queue', '顺序队列', 'EPHEMERAL_SEQUENTIAL', 'ListOrdered', 'green'], ['session', '会话管理', '心跳 · 超时判定', 'Activity', 'pink']],
