    metrics: [['globals', '全局事务', '次'], ['branches', '分支注册', '个'], ['commits', '二阶段提交', '次'], ['rollbacks', '回滚分支', '个'], ['undos', 'undo 补偿', '次']],
    nodes: [['tm', 'TM 事务管理器', '@GlobalTransactional', 'Route', 'blue'], ['tc', 'TC 协调器', '全局登记 · 二阶段裁决', 'Server', 'yellow'], ['rm', 'RM 分支事务', '订单 / 库存 / 账户', 'Boxes', 'green'], ['xid', '全局 XID', '沿调用链透传', 'Waypoints', 'pink'], ['undo', 'undo_log', '前镜像 · 逆向补偿', 'RotateCcw', 'pink'], ['tcc', 'TCC 状态机', 'Try / Confirm / Cancel', 'Recycle', 'green']],
