    nodes: [['producer', '顺序生产者', '按业务 key 发消息', 'Send', 'blue'], ['selector', 'MessageQueueSelector', 'orderId hash → 队列', 'Route', 'yellow'], ['q0', '队列 q0', '同订单消息排队', 'ListOrdered', 'yellow'], ['q1', '队列 q1', '另一订单排队', 'ListOrdered', 'yellow'], ['consumer', '顺序消费者', '单队列单线程串行', 'Cpu', 'green'], ['schedule', '定时调度', 'SCHEDULE_TOPIC 转投', 'Clock', 'pink']],
    edges: [['producer', 'selector', '声明队列选择器'], ['selector', 'q0', 'O1 全步骤落 q0'], ['selector', 'q1', 'O2 全步骤落 q1'], ['q0', 'consumer', '串行消费'], ['q1', 'consumer', '串行消费'], ['producer', 'schedule', '延迟级别消息']],
    code: ['// 顺序消息：同一订单的全部步骤必须进入同一队列（MessageQueueSelector）', 'SendResult r = producer.send(msg, (m, queueList) -> {', '  long oid = ((Order) m.getProperty("orderId")).id;', '  return queueList.get((int) (oid % queueList.size())); }, orderId);', '// 消费端：注册 MessageListenerOrderly —— 队列内单线程串行、失败自动挂起重试', 'consumer.registerMessageListener(new MessageListenerOrderly() {', '  public ConsumeOrderlyStatus consumeMessage(...) {', '    return doBusiness(msg) ? SUCCESS : SUSPEND_CURRENT_QUEUE_A_MOMENT;', '  } });', '// 延迟消息：delayTimeLevel 固定 18 档（1s/5s/10s/30s/1m/2m/…/1h/2h）', 'msg.setDelayTimeLevel(5);   // 第 5 档 = 1 分钟（不允许自定义秒数）', '// 实现：消息先进 SCHEDULE_TOPIC_XXXX 对应级别队列，定时调度到点转投业务 topic'],
    theory: [['全局 vs 分区有序', '顺序粒度 = 队列', '全局严格有序 = 所有消息挤一个队列，吞吐被压到单队列上限。RocketMQ 的模型是分区（队列）有序：同一个业务 key（如订单号）的消息恒入同一队列，该队列内单线程消费即保序——不同订单交错完全允许。'], ['顺序消费失败', 'SUSPEND_CURRENT_QUEUE_A_MOMENT', '并发消费失败可跳过（offset 继续推），顺序消费不行：跳过的步骤会让后续消息建立在缺失前提上。MessageListenerOrderly 失败后挂起当前队列、原地重试，直到成功或人工介入——宁可慢，不可乱。'], ['延迟消息', '18 级固定档位 + 定时转投', '延迟不是让消费者 sleep，而是 Broker 端延时投递：消息按 delayTimeLevel 先落 SCHEDULE_TOPIC_XXXX 的对应级别队列，定时线程到点后把消息转投到业务 topic 的真实队列，消费者在指定时刻后才看到它。级别固定 18 档（1s～2h），不允许任意秒数。']],
    goals: ['区分全局有序与分区有序，说出 MessageQueueSelector 保证同一订单同队列的原理', '解释顺序消费失败为何必须挂起当前队列重试而不是跳过，以及它与并发消费重试的区别', '说出延迟消息的实现路径：18 级档位 → SCHEDULE_TOPIC 落位 → 定时转投业务队列'],
