    metrics: [['submitted', '发起执行者', '个'], ['arrived', '到达协调点', '次'], ['released', '闸门放行', '次'], ['waiting', '真实阻塞', '人次']],
    nodes: [['main', '主线程', '编排 · 等待 / 发起', 'Monitor', 'blue'], ['pool', '线程池', '并行执行者', 'Boxes', 'yellow'], ['w1', '执行者 ①', '子任务 / 线程', 'Cpu', 'yellow'], ['w2', '执行者 ②', '子任务 / 线程', 'Cpu', 'yellow'], ['w3', '执行者 ③', '子任务 / 线程', 'Cpu', 'yellow'], ['coord', '协调器', 'Latch / Barrier / Semaphore', 'Waypoints', 'pink']],
    edges: [['main', 'pool', '提交并行任务'], ['pool', 'w1', '分配'], ['pool', 'w2', '分配'], ['pool', 'w3', '分配'], ['w1', 'coord', '到达'], ['coord', 'main', '放行 / 唤醒']],
    code: ['// CountDownLatch：主线程等 N 个子任务全部 countDown 后才放行（一次性）', 'CountDownLatch latch = new CountDownLatch(3);', 'executor.submit(() -> { User u = fetchUser(); latch.countDown(); });', 'executor.submit(() -> { Product p = fetchProduct(); latch.countDown(); });', 'latch.await(5, TimeUnit.SECONDS); // 挂起等待；超时兜底防永久阻塞', '// CyclicBarrier：N 个线程互相等齐，最后到达者触发打开；放行后自动复位可复用', 'CyclicBarrier barrier = new CyclicBarrier(3);', 'int phase = barrier.await(); // 先到者阻塞，最后一个到齐的线程返回并触发放行', '// Semaphore：acquire 拿许可进临界区，release 归还；不区分持有者，谁都能放', 'Semaphore sem = new Semaphore(2);', 'sem.acquire(); try { writeAuditLog(); } finally { sem.release(); }'],
    theory: [['CountDownLatch', 'await 等计数归零', '主线程 await 挂起等待，N 个子任务完成后各自 countDown，计数归零瞬间唤醒主线程——「等 N 件事齐」的一次性闸门。归零后不可复用；任务异常导致 countDown 不执行会让主线程永久阻塞，生产必须用 await(timeout)。'], ['CyclicBarrier', '线程互相等 · 可循环', 'N 个线程执行完阶段一后各自 await 在屏障前，先到者阻塞等待，最后一个到达者触发屏障打开，所有人同时进入阶段二；放行后屏障自动复位（cyclic），下一轮流程可重复使用。破坏或中断会抛 BrokenBarrierException。'], ['Semaphore', '许可计数 · 限流闸门', '构造时给 N 张许可：acquire 成功（许可-1）才能进临界区，release（许可+1）归还——控制同时进入资源的并发数（连接池、限流）。它不记录谁持有：任何线程都能 release，与锁的「持有者独占」本质不同。']],
    goals: ['区分三种协调语义：等 N 件事齐（Latch）、N 个线程互相等齐且可复用（Barrier）、许可限流（Semaphore）', '说清 CountDownLatch 一次性与 CyclicBarrier 可循环复用的差异，以及 await 阻塞与超时兜底', '理解 Semaphore 的 acquire/release 计数模型：谁都能放、不区分持有者，用于控制并发度而非互斥'],
    challenge: { task: '三个场景各运行一次：① 3 个子任务（用户/商品/库存）并行拉取，主线程 await 等齐后一次性合并 ② 3 个线程分片处理两阶段任务，观察「先到者阻塞、最后到达者触发放行」③ 3 个线程争抢 2 张许可，观察丙排队直到甲 release 才进场。期望：① 门闩 3→2→1→0、await 放行 1 次、三份数据齐后合并 ② A、B 先到真实阻塞（已到 1/3→2/3）、C 最后到达触发打开、三线程齐进阶段二 ③ 甲/乙直通（许可 0/2）、丙 pink 排队、甲 release 后丙才获得许可进场。', hint: '看协调器 token 的数字变化（门闩剩 N/3、屏障已到 N/3、许可剩 N/2）与执行者状态：黄=执行中、粉=等待/排队、绿=完成。', success: '能说出三件套各自解决哪种协作问题（等齐一次性 / 互相等可复用 / 并发限流），并解释为何 Semaphore 不区分持有者、CountDownLatch 必须配超时兜底。', requirements: [{ id: 'countdown', label: '① Latch 等齐合并', when: { scenario: 'countdown' } }, { id: 'barrier', label: '② Barrier 互相等齐', when: { scenario: 'barrier' } }, { id: 'semaphore', label: '③ Semaphore 许可限流', when: { scenario: 'semaphore' } }] },
    quiz: [
      { prompt: 'CountDownLatch(3) 中，主线程 latch.await() 什么时候返回？', choices: ['3 秒后自动超时返回', '3 个子任务各执行一次 countDown、计数归零时', '主线程自己调用三次 countDown 之后'], answer: 1, explanation: 'await 挂起主线程直到计数器归零——每个子任务完成时 countDown() 减一，三份数据齐备的瞬间主线程被唤醒。它是「等 N 件事齐」的一次性闸门。' },
      { prompt: 'CyclicBarrier 与 CountDownLatch 的本质区别是？', choices: ['Barrier 等外部事件，Latch 是线程互相等', 'Latch 一次性、归零即终局；Barrier 由最后到达者触发打开、放行后自动复位可循环复用，且是线程间互相等齐', 'Barrier 最多只能协调两个线程'], answer: 1, explanation: 'CountDownLatch 通常是主线程等子任务「报数」，归零后不可复用；CyclicBarrier 是 N 个对等线程互相等齐后一起放行，屏障复位后下一轮流程可继续使用（cyclic 由此得名）。' },
      { prompt: 'Semaphore(2) 场景下，第三个线程调用 acquire() 会怎样？', choices: ['立即抛异常拒绝执行', '直接获得许可继续执行', '阻塞排队，直到有线程 release 归还许可后才被唤醒'], answer: 2, explanation: '许可耗尽时 acquire 阻塞进入等待队列，前面某个线程执行完 release() 归还许可后，队首等待者被唤醒拿到许可进场。Semaphore 用许可数把并发流量闸在固定水位内。' },
    ],
    boundary: '固定 3 个执行者的教学模型；未模拟 await(timeout) 超时分支与中断异常、CyclicBarrier 的 BrokenBarrierException（线程中断/超时致屏障破坏）、Semaphore 公平/非公平队列与 AQS 内部实现（见 ReentrantLock 与 AQS 课）、release 超额与 tryAcquire 非阻塞路径、多阶段复杂流水线、以及实际业务中的线程池饱和与任务失败补偿策略；时间为教学示意。',
