    theory: [
      ['CAS 自旋', 'compareAndSet(expect, update)', '比较并交换是硬件原语：仅当内存当前值等于期望值才写入并返回成功，全程无锁。失败线程读新值重试（自旋）。代价是竞争激烈时反复空转；一次 CAS 只能保证「单个变量」的原子，复合状态需要版本戳辅助。'],
      ['ABA 问题', '值往返 · 版本戳拦截', 'T1 读到 A；T2 把值 A→B→A；T1 再 CAS 时值仍是 A → 误判「无人修改」而通过。对纯计数无害，对「值代表状态/栈顶/对象引用」的场景是灾难。AtomicStampedReference 把版本戳一并比较：每次写戳自增，T1 期望的旧戳已失效 → 拒绝。'],
      ['分段计数', 'LongAdder · base + Cell[]', '高并发下多线程死磕同一个 base 会让 CAS 连环失败。LongAdder 让冲突线程把增量写进各自哈希到的 Cell，sum() 再累加 base + Σcells——写竞争从全网争一个数降为每槽少数线程，代价是 sum() 是弱一致快照。'],
    ],
    goals: ['写出 CAS 的完整自旋循环（读期望 → CAS → 失败重读）并指出其无锁代价', '复现 ABA：值被改走又改回时无戳 CAS 为何误判、版本戳如何拦截', '说明 LongAdder 用「分流」而非「死磕」的原因与 sum() 的弱一致性'],
    challenge: { task: '三个场景各运行一次：① T1/T2 对共享槽位自增：T1 读 0、CAS(0→1) 成功；T2 读到的还是旧 0 → CAS(0→1) 失败（自旋 1），重读 1 后 CAS(1→2) 成功。计量口径：一次 CAS 调用 +1 次尝试（含失败的自旋调用）——CAS 调用共 3 次：T1 一次成功；T2 失败一次 + 重试成功一次 ② 复现 ABA：槽位初始 10，无戳版 T2 连续 CAS(10→20)、CAS(20→10) 把值改走又改回，T1 的 CAS(10→30) 直接通过（值确实仍是 10——表象欺骗，未被发现）；再换 AtomicStampedReference 重演同剧本：T2 两次写把 stamp 推到 2，T1 期望 stamp 0 → 值与戳双重比对，拦截 1 次（detect 1），重读后以新戳提交成功 ③ 8 线程并发自增：3 个线程在 base 直写成功，5 个撞车线程把增量写进自己的 Cell（分流 5），最终 sum()=base+Σcells 与总提交 8 一致。期望：① ops 3 · ok 2 · spins 1 · detect 0 ② ops 7 · ok 6 · detect 1（戳版拦截一次后重试提交）③ ops 13 · ok 8 · spread 5——核心认知：值相同 ≠ 没被动过。', hint: '看槽位值 token 与版本戳：② 无戳版 T1 提交时值确实仍是 10（表象欺骗成功）；戳版 T1 期望旧戳的提交被粉标拒绝，换新戳后才绿 ③ 看 cells 分段把单点竞争摊平、sum 与总数对齐。', success: '能画出 CAS 自旋循环、解释 ABA 为何危险与版本戳为何能拦截、说明 LongAdder 分段的取舍（吞吐 vs sum 弱一致）。', requirements: [{ id: 'spin', label: '① CAS 自旋 · 比较并交换', when: { scenario: 'spin' } }, { id: 'aba', label: '② ABA 复现 · 版本号拦截', when: { scenario: 'aba' } }, { id: 'adder', label: '③ LongAdder · 分段降竞争', when: { scenario: 'adder' } }] },
    quiz: [
      { prompt: 'CAS 失败后，乐观并发线程的常规做法是？', choices: ['park 挂起等待锁释放', '重读最新值再次 compareAndSet（自旋）', '抛出异常交给上层降级'], answer: 1, explanation: 'CAS 是无锁原语，失败只说明「期望值过期」：读新值重试即可，不需要锁也不该放弃——自旋次数随竞争强度上升，这是它的主要代价。' },
      { prompt: '为什么「值被改走又改回」能让 CAS 误判通过？', choices: ['CAS 只比较最终数值，无法感知中间修改历史', 'CAS 比较的是引用地址而不是值', 'JVM 缓存了旧值不刷新'], answer: 0, explanation: 'ABA 的名字即陷阱：T2 改到 B 又改回 A 后，T1 的期望 A 依旧匹配——比较的是「当前值 == 期望值」，历史动过几次无从得知。' },
      { prompt: 'LongAdder 相比 AtomicLong 的核心差异是？', choices: ['放弃原子性，最终结果可能错误', '把单点 base 竞争拆成 base + 多个 Cell 分流，sum() 需累加且为弱一致快照', '用读写锁保护计数'], answer: 1, explanation: 'LongAdder 牺牲 sum() 的强一致（快照求和），换取写入时把冲突摊到多个 Cell——写吞吐随并发上升不塌陷，适合计数型热点。' },
    ],
