    code: ['CompletableFuture.supplyAsync(() -> rpcA(), pool);      // 异步提交，立刻拿到 future', 'cfA.thenApply(r -> stepB(r));                              // 依赖上一段结果，串行接续', 'cfC.thenCombine(cfD, (c, d) -> merge(c, d));              // 等两个并行任务都完成再汇合', 'CompletableFuture.allOf(cf1, cf2, cf3).join();            // 多路并行，全部完成才继续', 'cf.exceptionally(ex -> fallback);                         // 链上任意异常 → 兜底接管、转为正常值', '// 异常传播：某环节抛异常，其下游所有依赖 stage 都不执行，直接以异常完结', '// commonPool 线程数 = CPU-1：一个阻塞任务长期占住线程 → 其他并行任务排队（传染）', '// 自定义有界线程池按任务类型隔离：阻塞型与计算型分池，互不拖累'],
